import { Button } from "@/registry/erbium/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogPanel,
  DialogTitle,
  DialogTrigger,
} from "@/registry/erbium/ui/dialog";
import { QRCode, QRCodeDownload, QRCodeImage } from "@/registry/erbium/ui/qr-code";

export default function QRCodeDialogExample() {
  return (
    <Dialog>
      <DialogTrigger render={<Button variant="outline">Show QR code</Button>} />
      <DialogPanel className="sm:max-w-xs">
        <DialogHeader>
          <DialogTitle>Open on your phone</DialogTitle>
          <DialogDescription>Scan the code with your camera.</DialogDescription>
        </DialogHeader>
        <DialogContent className="flex justify-center">
          <QRCode value="https://ui.erbium.app">
            <QRCodeImage aria-label="Scan to open ui.erbium.app" size="lg" />
            <QRCodeDownload fileName="erbium" buttonSize="sm">
              Download
            </QRCodeDownload>
          </QRCode>
        </DialogContent>
      </DialogPanel>
    </Dialog>
  );
}

import Example from "../examples/qr-code-dialog";

const Variant = () => <Example />;

export default Variant;
